documentationReport:
{
  "title": "Xikolo Notification Service: Comprehensive Documentation",
  "overview": "The Xikolo Notification Service is a central microservice within the Xikolo ecosystem, dedicated to managing and delivering user notifications across all Xikolo applications. Its primary function encompasses event-driven email delivery, in-app notification support, and robust user preference management. This service integrates with core Xikolo applications like Account, Course, Learnanalytics, News, and Pinboard, leveraging Msgr for inter-service communication and ensuring a unified notification experience. It also provides capabilities for event and mail log management.",
  "core_functionality": {
    "sending_notifications": {
      "description": "Other Xikolo services initiate notifications by publishing event data to Msgr. This data typically includes a timestamp and a link_to hash, which contains resource_key and resource_id for generating frontend and email links. The services.yml configuration defines the URLs for interacting with other core services.",
      "example": {
        "language": "ruby",
        "code": "data = {\n  timestamp: DateTime.now,\n  link_to: {\n    resource_key: 'Xikolo::Service::Resource',\n    resource_id:  '00000001-1234-4444-9999-000000000001'\n  },\n  # ... additional notification data\n}\nMsgr.publish(data, to: 'xikolo.service.resource.action')"
      }
    },
    "receiving_processing_notifications": {
      "description": "Within the Xikolo::NotificationService, incoming Msgr messages are processed based on routes defined in config/msgr.rb. Each route maps a specific Msgr topic (e.g., xikolo.service.resource.action) to a consumer method (e.g., consumer#method). New consumers or helpers must be created to handle incoming data, create the notification, and ensure the timestamp is forwarded. The Msgr Consumer component is central to this process."
    },
    "displaying_notifications": {
      "description": "For notifications to be displayed, a corresponding mail template must be added in app/views/{de|en}. Additionally, a description for the topic_exchange needs to be added to the frontend's locales under preferences.show.xikolo.service.resource.action. This allows users to manage their notification preferences directly from the frontend."
    }
  },
  "email_delivery_and_styling": {
    "description": "The service employs advanced strategies to ensure broad client compatibility for HTML emails, particularly with challenging clients like Microsoft Outlook.",
    "strategies": [
      {
        "name": "Inline Styles",
        "tool": "premailer",
        "detail": "Utilized to automatically inline CSS styles directly onto HTML elements, improving rendering consistency."
      },
      {
        "name": "Table-based Layouts",
        "tool": "inky",
        "detail": "Template helpers encapsulate robust table-based alignment techniques, which are fundamental for reliable email layouts."
      },
      {
        "name": "Foundation for Emails",
        "tool": "foundation",
        "detail": "Provides a structured approach and helpers for email design, strongly advising against custom styles, especially for responsiveness, to maintain compatibility."
      }
    ],
    "best_practices": [
      "Adherence to best practices, such as using full six-digit color codes (e.g., #666666) instead of shorthands, is recommended."
    ],
    "markdown_processing": "The MarkdownService is available for rendering rich content within notifications."
  },
  "email_branding_and_customization": {
    "description": "To avoid generic email templates and provide a branded experience, the service supports custom layouts. For specific brands, a dedicated folder should be created at services/notification/brand/<name>.",
    "customization_options": [
      "Custom templates in assets/views/layouts.",
      "Custom stylesheets named foundation_<name>.scss in assets/stylesheets."
    ]
  },
  "user_notification_management_and_preferences": {
    "description": "The system provides comprehensive tools for users to manage their notification settings:",
    "features": [
      "Preference Management: Users can manage their notification preferences via frontend locales, allowing them to enable or disable specific notification types.",
      "Components: The NotificationUserDisablesController and NotificationUserSettingsHelper are key components facilitating the management and persistence of user notification preferences."
    ]
  },
  "system_components_and_interactions": {
    "description": "The Xikolo Notification Service is built upon a set of interconnected components:",
    "components": [
      {
        "name": "Xikolo::NotificationService (Notification Service)",
        "role": "The core microservice orchestrating all notification-related functionalities."
      },
      {
        "name": "Msgr / Msgr Consumer",
        "role": "The messaging backbone for inter-service communication, handling both publishing and consuming notification events."
      },
      {
        "name": "Mailer",
        "role": "Responsible for constructing and sending email notifications."
      },
      {
        "name": "Sidekiq Worker",
        "role": "Used for asynchronous processing of tasks, likely including email sending and other background notification jobs, ensuring responsiveness."
      },
      {
        "name": "NotificationUserDisablesController",
        "role": "Manages user requests to disable or enable specific notification types."
      },
      {
        "name": "NotificationUserSettingsHelper",
        "role": "Provides utility functions for accessing and manipulating user notification settings."
      },
      {
        "name": "MarkdownService",
        "role": "Processes Markdown content for inclusion in notifications, ensuring consistent formatting."
      },
      {
        "name": "TrackingMailInterceptor",
        "role": "Intercepts outgoing emails, likely for tracking delivery status, opens, or clicks."
      },
      {
        "name": "premailer",
        "role": "A utility for inlining CSS styles into HTML emails."
      },
      {
        "name": "inky",
        "role": "A templating language/helper for creating responsive email layouts using tables."
      },
      {
        "name": "foundation (Foundation for Emails)",
        "role": "A framework providing a structured approach and helpers for robust email design."
      }
    ]
  },
  "event_and_mail_log_management": {
    "description": "The service includes capabilities for managing logs related to notification events and sent emails, providing an audit trail and aiding in debugging and monitoring the notification delivery process."
  },
  "key_interactions": [
    "External services publish events to Msgr.",
    "Msgr Consumer in Xikolo::NotificationService receives and processes events.",
    "Mailer generates emails, potentially using MarkdownService for content and premailer/inky/foundation for styling.",
    "Sidekiq Worker handles asynchronous email sending and other background tasks.",
    "TrackingMailInterceptor monitors outgoing emails.",
    "NotificationUserDisablesController and NotificationUserSettingsHelper manage user preferences, influencing which notifications are sent.",
    "The service interacts with other core Xikolo services (Account, Course, Learnanalytics, News, Pinboard) as configured in services.yml."
  ]
}
